"use client";
import { Suspense, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { setCookie } from "cookies-next";
import { primaryRole } from "@/lib/role";
import { partnerLinks } from "@/lib/partnerLinks";
import { apiClient } from "@/lib/apiClient";

function AuthCallback() {
  const searchParams = useSearchParams();
  const router = useRouter();

  useEffect(() => {
    const provider = searchParams.get("p"); // "g" | "f"
    const code = searchParams.get("code");
    const state = searchParams.get("state") ?? "/";
    const oauthError = searchParams.get("error");
    const returnTo = decodeURIComponent(state);
    const loginFallback = `/auth/login?returnTo=${encodeURIComponent(returnTo)}`;

    if (oauthError || !code || !provider) {
      router.replace(
        loginFallback +
          `&error=${encodeURIComponent("Sign-in was cancelled.")}`,
      );
      return;
    }

    const providerName = provider === "g" ? "google" : "facebook";
    const redirectUri = `${window.location.origin}/auth/callback?p=${provider}`;

    // apiv3 sosyal login (app.token, tarayıcı → /api/apiv3 proxy). Login ile aynı
    // sözleşme: { token (Sanctum), token_old (api_token), user }.
    apiClient<any>(`/auth/${providerName}/callback`, {
      method: "POST",
      body: { code, redirect_uri: redirectUri },
    })
      .then((res) => {
        const roles: string[] = Array.isArray(res?.user?.roles) ? res.user.roles : [];
        const b2bRole = roles.includes("operator") ? "tour operator" : roles.includes("blogger") ? "blogger" : null;
        if (res?.token && b2bRole) {
          // Operatör/blogger ana siteye giremez (panelleri business'ta) — token yazılmaz.
          router.replace(
            loginFallback +
              `&error=${encodeURIComponent(`This is a ${b2bRole} account. Please sign in at the TravelShop Business panel: ${partnerLinks.login}`)}`,
          );
          return;
        }
        if (res?.token) {
          const maxAge = 60 * 60 * 24 * 365;
          setCookie("auth-token-v3", res.token, { maxAge });
          setCookie("auth-token", res.token_old, { maxAge });
          setCookie("user-email", res.user.email, { maxAge });
          setCookie("user-avatar", res.user.avatar ?? "", { maxAge });
          setCookie("user-full-name", res.user.name, { maxAge });
          setCookie("user-id", res.user.id.toString(), { maxAge });
          if (res.user?.roles && Array.isArray(res.user.roles)) {
            setCookie("user-role", primaryRole(res.user.roles), { maxAge });
          }
          window.location.href = returnTo || "/";
        } else {
          router.replace(
            loginFallback +
              `&error=${encodeURIComponent("Sign-in failed. Please try again.")}`,
          );
        }
      })
      .catch(() => {
        router.replace(
          loginFallback +
            `&error=${encodeURIComponent("Something went wrong. Please try again.")}`,
        );
      });
  }, [searchParams, router]);

  return <AuthCallbackUI />;
}

function AuthCallbackUI() {
  return (
    <div
      className="tw-min-h-screen tw-flex tw-items-start tw-justify-center tw-pt-32 tw-px-4"
      style={{ background: "#faf9fc" }}
    >
      <style>{`
        @keyframes tsb-spin {
          to { transform: rotate(360deg); }
        }
        .tsb-spinner {
          width: 48px;
          height: 48px;
          border-radius: 50%;
          border: 3px solid #ebe7f0;
          border-top-color: #854ec9;
          animation: tsb-spin 0.8s linear infinite;
        }
      `}</style>
      <div className="tw-w-full tw-max-w-[440px]">
        <div
          className="tw-bg-white tw-rounded-[20px] tw-p-8"
          style={{ boxShadow: "0 4px 24px rgba(20,16,28,0.08)" }}
        >
          <div className="tw-flex tw-flex-col tw-items-center tw-gap-5 tw-py-4">
            <div className="tsb-spinner" />
            <div className="tw-text-center">
              <h1
                className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-1 tw-mt-0"
                style={{ letterSpacing: "-0.02em" }}
              >
                Completing sign-in
              </h1>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-m-0">
                Verifying your account, you&apos;ll be redirected in a moment…
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function AuthCallbackPage() {
  return (
    <Suspense fallback={<AuthCallbackUI />}>
      <AuthCallback />
    </Suspense>
  );
}
